<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import RankingTable from '../components/RankingTable.vue';import {create as review} from '../api/reviews';import {create as report} from '../api/reports';import {download} from '../api/client';import {useAsync} from '../hooks/useAsync';import {DECISIONS} from '../constants/enums';import {date} from '../utils/format';const props=defineProps<{data:Workspace;canWrite:boolean;isAdmin:boolean;refresh:()=>Promise<void>}>();const completed=computed(()=>props.data.runs.filter(r=>r.status==='completed'));const id=ref(''),note=ref(''),decision=ref('accepted'),ack=ref(false);const active=computed(()=>completed.value.find(r=>r.id===id.value)||completed.value[0]);const {busy,error,execute}=useAsync();async function submit(){await execute(async()=>{await review({run_id:active.value?.id,note:note.value,decision:decision.value,accept_warning:ack.value});note.value='';await props.refresh()})}async function publish(run_id:string){await execute(async()=>{await report({run_id,title:'模拟航段权衡复核 · '+new Date().toISOString().slice(0,10)});await props.refresh()})};</script><template><PageHeading code="06 / CHOICE REVIEW" title="把权衡依据，与名次一起留下。" description="分析员记录方向、原矩阵、CR和敏感性边界。管理员确认最新人工意见接受后归档。"/><section class="paper" v-if="canWrite"><h2>提交权衡复核</h2><form class="grid-form" @submit.prevent="submit"><label>已完成运行<select aria-label="复核运行" :value="active?.id" @change="id=($event.target as HTMLSelectElement).value;ack=false"><option v-for="r in completed" :key="r.id" :value="r.id">{{data.judgments.find(j=>j.id===r.judgment_id)?.name}} · {{r.created_at.slice(11,19)}}</option></select></label><label>复核判断<select v-model="decision"><option value="accepted">接受并记录假设</option><option value="needs_attention">需要继续核查</option></select></label><Notice v-if="active?.result.ahp.cr_warning" error class="wide">本次CR高于阈值。若仍提交接受意见，必须明确确认已阅读警告，保留解释。</Notice><label v-if="active?.result.ahp.cr_warning" class="acknowledge wide"><input type="checkbox" v-model="ack"/>我已阅读高CR警告，并将在意见中记录判断依据。</label><label class="wide">依据与边界<textarea aria-label="依据与边界" required minlength="8" rows="3" v-model="note" placeholder="记录指标方向、CR、名次扰动范围与模拟场景的解释边界。"/></label><button :disabled="busy||!active">提交权衡复核</button></form></section><Notice v-if="error" error>{{error}}</Notice><section class="paper" v-if="active"><h2>本次备选方案</h2><RankingTable :rows="active.result.alternatives"/></section><section class="paper"><h2>复核记录</h2><Empty v-if="!data.reviews.length">计算完成后，请核对CR警告与不可排名状态，再提交人工意见。</Empty><article class="review-record" v-for="r in data.reviews" :key="r.id"><div><span :class="['status',r.decision]">{{DECISIONS[r.decision]}}</span><small>{{r.author}} · {{date(r.created_at)}}</small></div><p>{{r.note}}</p><small v-if="r.accept_warning">已明确阅读高CR警告</small><button v-if="isAdmin&&r.decision==='accepted'&&!data.reports.some(p=>p.run_id===r.run_id)" class="secondary" :disabled="busy" @click="publish(r.run_id)">批准并归档</button></article></section><section class="paper"><h2>航册归档</h2><article class="report-row" v-for="p in data.reports" :key="p.id"><div><h3>{{p.title}}</h3><small>{{date(p.created_at)}} · {{p.published_by}}</small></div><button class="secondary" @click="execute(()=>download(p.id))">下载CSV　↓</button></article></section><details class="audit-details"><summary>操作留痕 / 最近{{data.audit.length}}条</summary><div class="table-scroll"><table><thead><tr><th>操作者</th><th>动作</th><th>状态</th></tr></thead><tbody><tr v-for="a in data.audit" :key="a.id"><td>{{a.actor}}</td><td>{{a.action}}</td><td>{{a.status}}</td></tr></tbody></table></div></details></template>
